        } else {
            $tokenUrl = $this->config->getHost() . "/connect/token";
            $tokenUrl = str_replace('/v3.0', '', $tokenUrl);
            // print("tokenUrl: " . $tokenUrl . "\n");
            $postData = "grant_type=client_credentials" . "&client_id=" . $this->config->getClientId() . "&client_secret=" . $this->config->getClientSecret();            try {
