            }

            $result = json_decode($responseJson, true);
            if (is_null($result)) {
                if (strlen(trim($responseJson)) > 0) {
                    throw new ApiException($responseJson);
                } else {
                    throw new ApiException(sprintf('empty token (%s)', $responseJson));
                }
            } else if (!isset($result["access_token"]) || strlen(trim($result["access_token"])) == 0) {
